CREATE TABLE public.transicao_parametros (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid UNIQUE REFERENCES public.clientes(id) ON DELETE CASCADE, marcos jsonb NOT NULL DEFAULT '[]', regime_compensacao_padrao text NOT NULL DEFAULT 'sem', limite_diario_padrao numeric NOT NULL DEFAULT 8, multiplicadores_intensidade jsonb NOT NULL DEFAULT '{"baixo":0.75,"normal":1,"alto":1.25,"pico":1.5}', indices_reposicao jsonb NOT NULL DEFAULT '{"ativo":true,"ferias":8.33,"absenteismo":0,"arredondar":true}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transicao_setores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE, ordem int NOT NULL DEFAULT 0, nome text NOT NULL DEFAULT 'Setor', funcionarios_atuais int NOT NULL DEFAULT 0, funcionarios_por_sexo jsonb NOT NULL DEFAULT '{}', parciais jsonb NOT NULL DEFAULT '{"qtd":0,"horas":0}', funcionamento jsonb NOT NULL DEFAULT '{}', postos jsonb NOT NULL DEFAULT '[]', intensidade_dias jsonb NOT NULL DEFAULT '{}', regime_compensacao text, limite_diario numeric, insalubre boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transicao_datas_especiais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), setor_id uuid NOT NULL REFERENCES public.transicao_setores(id) ON DELETE CASCADE, data date NOT NULL, nivel text NOT NULL DEFAULT 'alto', observacao text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transicao_cenarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE, nome text NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transicao_jornadas_ia (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), setor_id uuid NOT NULL REFERENCES public.transicao_setores(id) ON DELETE CASCADE, marco text NOT NULL, payload_ia jsonb NOT NULL DEFAULT '{}', validacao jsonb NOT NULL DEFAULT '{}', editado boolean NOT NULL DEFAULT false, escala_id uuid REFERENCES public.escalas_revezamento(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['transicao_parametros','transicao_setores','transicao_datas_especiais','transicao_cenarios','transicao_jornadas_ia'] LOOP
 EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
 EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
 EXECUTE format('CREATE POLICY "Authenticated full access" ON public.%I FOR ALL TO authenticated USING (true) WITH CHECK (true)', t);
END LOOP; END $$;
CREATE TRIGGER trg_tp_upd BEFORE UPDATE ON public.transicao_parametros FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER trg_tsx_upd BEFORE UPDATE ON public.transicao_setores FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER trg_tj_upd BEFORE UPDATE ON public.transicao_jornadas_ia FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();